examples.title:
a = {1, 2, 3}
a.intersection_update({2, 3, 4})
print(sorted(a))

a = {'a', 'b', 'c'}
a.difference_update({'b'})
print(sorted(a))

a = {1, 2, 3}
b = {3, 4}
print(sorted(a.symmetric_difference(b)))

small = {1, 2}
large = {1, 2, 3}
print(small.issubset(large))
print(large.issuperset(small))

morning = {'tea', 'toast'}
evening = {'rice', 'dal'}
print(morning.isdisjoint(evening))
